"""Small atomic JSON-backed store used by :mod:`evalledger.ledger`."""

import copy
import json
from pathlib import Path


class JsonStore:
    """Keep a JSON document in memory and commit transactions atomically.

    Actions always receive a deep copy.  Consequently, an exception from an
    action (or from writing its result) cannot expose a partially changed
    in-memory ledger.
    """

    def __init__(self, path):
        self.path = Path(path)
        self.data = (
            json.loads(self.path.read_text(encoding="utf-8"))
            if self.path.exists()
            else {}
        )

    def transact(self, action):
        candidate = copy.deepcopy(self.data)
        result = action(candidate)

        # Exact replays are genuine no-ops: do not even rewrite the file.
        if candidate == self.data:
            return copy.deepcopy(result)

        # Serialize before touching the filesystem, then write the whole
        # candidate before replacing the committed document.  There is only one
        # writer, so a sibling temporary file is sufficient.
        serialized = json.dumps(candidate, separators=(",", ":"))
        self.path.parent.mkdir(parents=True, exist_ok=True)
        temp = self.path.with_name(self.path.name + ".tmp")
        temp.write_text(serialized, encoding="utf-8")
        temp.replace(self.path)

        self.data = candidate
        return copy.deepcopy(result)


def identifier(value):
    """Validate and return a contract identifier."""
    if not isinstance(value, str) or not value or len(value) > 128:
        raise ValueError("invalid identifier")
    return value


def integer(value, low=0, high=1_000_000_000):
    """Validate an integer while explicitly excluding booleans."""
    if type(value) is not int or not low <= value <= high:
        raise ValueError("invalid integer")
    return value
